    q=q.view(-1,4,48).transpose(0,1); k=k.view(-1,4,48).transpose(0,1); v=v.view(-1,4,48).transpose(0,1)
    a = torch.softmax(q@k.transpose(1,2)/math.sqrt(48),-1)
